for emoji, keywords in EMOJI_KEYWORDS.items():
    for kw in keywords:
        KEYWORD_TO_EMOJI[kw.lower()] = emoji

def find_emoji_for_words(words):
    """
    Scans an array of words and returns the most relevant Unicode emoji, or None.
    """
    import re
    for w in words:
        clean = re.sub(r'[^\w]', '', w).lower()
        if clean in KEYWORD_TO_EMOJI:
            return KEYWORD_TO_EMOJI[clean]
    return None
